from AlgorithmImports import *
from collections import deque
from math import floor


class IndependentSpyAaplStrategies(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {
            ticker: self.AddEquity(ticker, Resolution.Daily).Symbol
            for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        }

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.closes = {symbol: deque(maxlen=101) for symbol in self.symbols.values()}
        self.previous_closes = {}

        self.aapl_rsi = None
        self.aapl_rsi_seed_gains = []
        self.aapl_rsi_seed_losses = []
        self.aapl_avg_gain = None
        self.aapl_avg_loss = None

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0
        self.strategy_a_percent = 1.0

    def OnData(self, data: Slice):
        bars = {}
        for symbol in self.symbols.values():
            if data.Bars.ContainsKey(symbol):
                bars[symbol] = data.Bars[symbol]

        for symbol, bar in bars.items():
            prior_close = self.previous_closes.get(symbol)
            self.closes[symbol].append(float(bar.Close))

            if symbol == self.aapl and prior_close is not None:
                change = float(bar.Close) - prior_close
                gain = max(change, 0.0)
                loss = max(-change, 0.0)

                if self.aapl_avg_gain is None:
                    self.aapl_rsi_seed_gains.append(gain)
                    self.aapl_rsi_seed_losses.append(loss)

                    if len(self.aapl_rsi_seed_gains) == 14:
                        self.aapl_avg_gain = sum(self.aapl_rsi_seed_gains) / 14.0
                        self.aapl_avg_loss = sum(self.aapl_rsi_seed_losses) / 14.0
                        self.aapl_rsi = self.CalculateRsi()
                else:
                    self.aapl_avg_gain = (
                        self.aapl_avg_gain * 13.0 + gain
                    ) / 14.0
                    self.aapl_avg_loss = (
                        self.aapl_avg_loss * 13.0 + loss
                    ) / 14.0
                    self.aapl_rsi = self.CalculateRsi()

            self.previous_closes[symbol] = float(bar.Close)

        if len(bars) != len(self.symbols):
            return

        if (
            len(self.closes[self.spy]) < 101
            or len(self.closes[self.aapl]) < 4
            or self.aapl_rsi is None
        ):
            return

        spy_closes = list(self.closes[self.spy])
        spy_yesterday_close = spy_closes[-2]
        spy_today_close = spy_closes[-1]
        spy_yesterday_sma = sum(spy_closes[-101:-1]) / 100.0
        spy_today_sma = sum(spy_closes[-100:]) / 100.0

        aapl_closes = list(self.closes[self.aapl])
        aapl_red_three_days = (
            aapl_closes[-1] < aapl_closes[-2]
            and aapl_closes[-2] < aapl_closes[-3]
            and aapl_closes[-3] < aapl_closes[-4]
        )

        spy_crosses_above = (
            spy_yesterday_close <= spy_yesterday_sma
            and spy_today_close > spy_today_sma
        )
        spy_crosses_below = (
            spy_yesterday_close >= spy_yesterday_sma
            and spy_today_close < spy_today_sma
        )

        available_cash = self.Portfolio.Cash

        if self.strategy_a_shares > 0 and spy_crosses_below:
            self.MarketOrder(self.spy, -self.strategy_a_shares)
            available_cash += self.strategy_a_shares * spy_today_close
            self.strategy_a_shares = 0

        if self.strategy_b_shares > 0 and self.aapl_rsi > 60:
            aapl_close = float(bars[self.aapl].Close)
            self.MarketOrder(self.aapl, -self.strategy_b_shares)
            available_cash += self.strategy_b_shares * aapl_close
            self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and spy_crosses_above:
            shares = floor(
                self.strategy_a_percent * self.Portfolio.TotalPortfolioValue
                / spy_today_close
            )
            if shares > 0:
                self.MarketOrder(self.spy, shares)
                self.strategy_a_shares = shares
                available_cash -= shares * spy_today_close

        if self.strategy_b_shares == 0 and aapl_red_three_days:
            aapl_close = float(bars[self.aapl].Close)
            if available_cash >= 20_000:
                shares = floor(20_000 / aapl_close)
                if shares > 0:
                    self.MarketOrder(self.aapl, shares)
                    self.strategy_b_shares = shares

    def CalculateRsi(self):
        if self.aapl_avg_loss == 0:
            return 100.0
        if self.aapl_avg_gain == 0:
            return 0.0
        rs = self.aapl_avg_gain / self.aapl_avg_loss
        return 100.0 - (100.0 / (1.0 + rs))
